-    read_versioned(bytes, RECORD_FORMAT)
+    let mut record: RunRecord = read_versioned(bytes, RECORD_FORMAT)?;
+    // Review cr-jl4fix4-2: a record from between the raw list and the
+    // exact marker keeps identities already; only one with neither key is
+    // text-only.
+    if !record.left_in_place_exact {
+        if let Ok(serde_json::Value::Object(keys)) =
+            serde_json::from_slice::<serde_json::Value>(bytes)
+        {
+            if keys.contains_key("left_in_place_raw") && !keys.contains_key("left_in_place_exact") {
+                record.left_in_place_exact = true;
+            }
+        }
+    }
+    Ok(record)
 }

 /// Write `value` to `path` whole: a temp file beside it, synced, then
 /// renamed over it.
 ///
 /// Review cr-jl3a-2: each write stages in a file of its own — two writers
 /// of one document (two `blit jobs` commands settling the same run) never
 /// share one — and the folder is synced after the rename, so the new
 /// document survives a crash.
 pub fn write_document(path: &Path, value: &impl Serialize) -> io::Result<()> {
     let name = path.file_name().ok_or_else(|| {
         io::Error::new(
             io::ErrorKind::InvalidInput,
             format!("{} names no file", path.display()),
         )
     })?;
     let dir = path
         .parent()
         .filter(|dir| !dir.as_os_str().is_empty())
         .unwrap_or(Path::new("."));
     let mut staged = std::ffi::OsString::from(".");
     staged.push(name);
     staged.push(format!(".{}{TEMP_SUFFIX}", crate::job_log::new_run_id()?));
     let temp = dir.join(staged);
     let result = (|| {
         let mut file = OpenOptions::new()
             .write(true)
             .create_new(true)
             .open(&temp)?;
         serde_json::to_writer_pretty(&mut file, value)?;
         file.write_all(b"\n")?;
         crate::job_log::sync_all(&file)?;
         drop(file);
         fs::rename(&temp, path)?;
         crate::job_log::sync_dir(dir);
         Ok(())
     })();
     if result.is_err() {
         let _ = fs::remove_file(&temp);
     }
     result
 }

