 1199: /// Every log in `dir` for the run `run_id` — in `role` only, when given —
 1200: /// ordered by role, participant and attempt. Errors only when `run_id`
 1201: /// cannot name a log or `dir` cannot be read; a missing `dir` holds no logs.
 1202: pub fn logs_for_run(dir: &Path, run_id: &str, role: Option<Role>) -> eyre::Result<Vec<FoundLog>> {
 1203:     check_id("run ID", run_id)?;
 1204:     let entries = match fs::read_dir(dir) {
 1205:         Ok(entries) => entries,
 1206:         Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
 1207:         Err(error) => return Err(eyre::Report::new(error)),
 1208:     };
 1209:     let mut found: Vec<FoundLog> = Vec::new();
 1210:     for entry in entries.flatten() {
 1211:         let name = entry.file_name();
 1212:         let Some(name) = name.to_str() else { continue };
 1213:         let (stem, finished) = if let Some(stem) = name.strip_suffix(FINISHED_SUFFIX) {
 1214:             (stem, true)
 1215:         } else if let Some(stem) = name.strip_suffix(PARTIAL_SUFFIX) {
 1216:             (stem, false)
 1217:         } else {
 1218:             continue;
 1219:         };
 1220:         let Some(key) = LogKey::from_file_stem(stem) else {
 1221:             continue;
 1222:         };
 1223:         if key.run_id != run_id || role.is_some_and(|role| role != key.role) {
 1224:             continue;
 1225:         }
 1226:         // A run caught between finishing and removing its partial shows
 1227:         // once, as finished.
 1228:         if let Some(seen) = found.iter_mut().find(|seen| seen.key == key) {
 1229:             if finished {
 1230:                 *seen = FoundLog {
 1231:                     key,
 1232:                     path: entry.path(),
 1233:                     finished,
 1234:                 };
 1235:             }
 1236:             continue;
 1237:         }
 1238:         found.push(FoundLog {
 1239:             key,
 1240:             path: entry.path(),
 1241:             finished,
 1242:         });
 1243:     }
 1244:     found.sort_by(|a, b| {
 1245:         (a.key.role.as_str(), &a.key.participant, a.key.attempt).cmp(&(
 1246:             b.key.role.as_str(),
 1247:             &b.key.participant,
