  651:     fn append(&mut self, ts_ms: u64, body: EventBody) {
  652:         let Some(file) = self.file.as_mut() else {
  653:             return;
  654:         };
  655:         if let Err(error) = file.append(ts_ms, body) {
  656:             self.stop(error);
  657:         }
  658:     }
  659: 
  660:     fn sync(&mut self) {
  661:         let Some(file) = self.file.as_mut() else {
  662:             return;
  663:         };
  664:         if !file.unsynced {
  665:             return;
  666:         }
  667:         if let Err(error) = file.sync() {
  668:             self.stop(error);
  669:         }
  670:     }
  671: 
  672:     /// How long until what was written is due to be synced.
  673:     fn until_sync(&self, interval: Duration) -> Duration {
  674:         match &self.file {
  675:             Some(file) if file.unsynced => interval.saturating_sub(file.last_sync.elapsed()),
  676:             _ => IDLE_WAIT,
  677:         }
  678:     }
  679: 
  680:     /// Logging stops at the first write that fails; the transfer goes on.
  681:     fn stop(&mut self, error: io::Error) {
  682:         let reason = format!("could not write the log: {error}");
  683:         if let Some(mut file) = self.file.take() {
  684:             // Best effort. The failed write may have left part of a line, so
  685:             // end it first and the marker stands as a line of its own.
  686:             let _ = file.out.write_all(b"\n").and_then(|()| {
  687:                 file.append(
  688:                     now_ms(),
  689:                     EventBody::LogIncomplete {
  690:                         reason: reason.clone(),
  691:                     },
  692:                 )?;
  693:                 file.sync()
  694:             });
  695:         }
  696:         self.report.problem.get_or_insert(reason);
  697:     }
  698: 
  699:     fn finish(mut self, keep: usize) -> LogReport {
  700:         self.report.complete = self.file.is_some();
  701:         // Close the partial before compressing it; it was synced already.
  702:         drop(self.file.take());
  703:         let Some(lock) = self.lock.take() else {
  704:             return self.report;
  705:         };
  706:         match compress_into_place(&self.dir, &self.stem, None) {
  707:             Ok(finished) => self.report.path = Some(finished),
  708:             Err(error) => {
  709:                 self.report.problem.get_or_insert_with(|| {
  710:                     format!("could not finish the log (the next start finishes it): {error}")
  711:                 });
  712:                 return self.report;
  713:             }
  714:         }
  715:         drop(lock);
  716:         let _ = fs::remove_file(path_of(&self.dir, &self.stem, LOCK_SUFFIX));
  717:         if let Err(error) = prune(&self.dir, keep) {
  718:             log::warn!("job logs: pruning {} failed: {error}", self.dir.display());
  719:         }
  720:         self.report
  721:     }
  722: }
