  724: struct PartialFile {
  725:     out: BufWriter<File>,
  925:     /// Logs this call finished, closed as interrupted unless they already
  926:     /// held their `run-end`.
  927:     pub finished: Vec<PathBuf>,
  928:     /// Partials left alone because a running writer still owns them.
  929:     pub live: usize,
  930:     /// Logs that could not be recovered, and why; they stay as they are for
  931:     /// the next attempt.
  932:     pub problems: Vec<String>,
  933: }
  934: 
  935: /// Finish every log in `dir` that a stopped process left behind (run at
  936: /// startup). A partial whose lock is free has no writer: it gets a `run-end`
  937: /// marked interrupted — unless it already ends with one, the crash having
  938: /// come while it was being compressed — and is compressed into place.
  939: /// Partials a running writer holds are left alone.
  940: pub fn recover(dir: &Path) -> Recovery {
  941:     let mut recovery = Recovery::default();
  942:     let entries = match fs::read_dir(dir) {
  943:         Ok(entries) => entries,
  944:         Err(error) if error.kind() == io::ErrorKind::NotFound => return recovery,
  945:         Err(error) => {
  946:             recovery
  947:                 .problems
  948:                 .push(format!("could not read {}: {error}", dir.display()));
  949:             return recovery;
  950:         }
  951:     };
  952:     let mut stems: Vec<String> = Vec::new();
  953:     for entry in entries.flatten() {
  954:         let name = entry.file_name();
  955:         let Some(name) = name.to_str() else { continue };
  956:         let Some(stem) = name
  957:             .strip_suffix(PARTIAL_SUFFIX)
  958:             .or_else(|| name.strip_suffix(TEMP_SUFFIX))
  959:         else {
  960:             continue;
  961:         };
  962:         if LogKey::from_file_stem(stem).is_some() && !stems.iter().any(|seen| seen == stem) {
  963:             stems.push(stem.to_string());
  964:         }
  965:     }
  966:     stems.sort();
  967:     for stem in stems {
  968:         match recover_one(dir, &stem) {
  969:             Ok(Recovered::Finished(path)) => recovery.finished.push(path),
  970:             Ok(Recovered::Live) => recovery.live += 1,
  971:             Ok(Recovered::Tidied) => {}
  972:             Err(error) => recovery.problems.push(format!("{stem}: {error}")),
  973:         }
  974:     }
  975:     recovery
  976: }
  977: 
  978: enum Recovered {
  979:     Finished(PathBuf),
  980:     Live,
  981:     /// Only leftovers of a log already finished were removed.
  982:     Tidied,
  983: }
  984: 
  985: fn recover_one(dir: &Path, stem: &str) -> io::Result<Recovered> {
  986:     let lock_path = path_of(dir, stem, LOCK_SUFFIX);
  987:     let lock = open_lock_file(&lock_path)?;
  988:     match lock.try_lock() {
  989:         Ok(()) => {}
  990:         Err(TryLockError::WouldBlock) => return Ok(Recovered::Live),
  991:         Err(TryLockError::Error(error)) => return Err(error),
  992:     }
  993:     let partial = path_of(dir, stem, PARTIAL_SUFFIX);
  994:     let recovered = if !partial.exists() {
  995:         // A temp file whose partial is gone.
  996:         remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
  997:         Recovered::Tidied
  998:     } else if path_of(dir, stem, FINISHED_SUFFIX).exists() {
  999:         // Finished before the crash; only removing the partial was lost.
 1000:         fs::remove_file(&partial)?;
 1001:         remove_if_present(&path_of(dir, stem, TEMP_SUFFIX))?;
 1002:         Recovered::Tidied
 1003:     } else {
 1004:         let lost_start = close_interrupted(&partial)?;
 1005:         // Review cr-jlfix1-1: typed reading needs the header, so a log whose
 1006:         // start was lost (a crash before its first sync) gets one rebuilt
 1007:         // from its name, at the front of the finished file.
 1008:         let header = match (lost_start, LogKey::from_file_stem(stem)) {
 1009:             (true, Some(key)) => Some(rebuilt_header(&key, &partial)?),
 1010:             _ => None,
 1011:         };
 1012:         Recovered::Finished(compress_into_place(dir, stem, header.as_deref())?)
 1013:     };
 1014:     drop(lock);
 1015:     let _ = fs::remove_file(&lock_path);
 1016:     Ok(recovered)
 1017: }
