 1026: /// Append `run-end` (interrupted) to a partial that lacks one, keeping the
 1027: /// partial's modified time. Returns whether the partial's start — its
 1028: /// `run-start` header — was lost. Reads the partial line by line without
 1029: /// the header check, since recovering a damaged log is the point.
 1030: fn close_interrupted(partial: &Path) -> io::Result<bool> {
 1031:     let mut last = None;
 1032:     let mut lost_start = true;
 1033:     let mut first = true;
 1034:     let mut lines = decode(File::open(partial)?)?;
 1035:     let mut buf = Vec::new();
 1036:     loop {
 1037:         buf.clear();
 1038:         if lines.read_until(b'\n', &mut buf)? == 0 {
 1039:             break;
 1040:         }
 1041:         let text = buf.trim_ascii();
 1042:         if text.is_empty() {
 1043:             continue;
 1044:         }
 1045:         if first {
 1046:             first = false;
 1047:             lost_start = check_header(text).is_err();
 1048:         }
 1049:         if let Ok(event) = serde_json::from_slice::<Event>(text) {
 1050:             last = Some(event);
 1051:         }
 1052:     }
 1053:     if let Some(Event {
 1054:         body: EventBody::RunEnd { .. },
 1055:         ..
 1056:     }) = last
 1057:     {
 1058:         return Ok(lost_start);
 1059:     }
 1060:     let mut file = OpenOptions::new().read(true).append(true).open(partial)?;
 1061:     let modified = file.metadata()?.modified()?;
 1062:     let mut line = Vec::new();
 1063:     // A torn last line gets its end, so the new event is a line of its own.
 1064:     if file.metadata()?.len() > 0 {
 1065:         let mut byte = [0u8; 1];
 1066:         file.seek(SeekFrom::End(-1))?;
 1067:         file.read_exact(&mut byte)?;
 1068:         if byte[0] != b'\n' {
 1069:             line.push(b'\n');
 1070:         }
 1071:     }
 1072:     serde_json::to_writer(
 1073:         &mut line,
 1074:         &Event {
 1075:             ts_ms: now_ms(),
 1076:             // Review cr-jlfix2-2: with nothing surviving, the start was
 1077:             // lost too, and the header rebuilt for it holds 0.
 1078:             seq: last.map_or(1, |event| event.seq + 1),
 1079:             body: EventBody::RunEnd {
 1080:                 outcome: Outcome::Interrupted,
 1081:                 detail: Some(if lost_start {
 1082:                     format!("{RECOVERED_NOTE}{LOST_START_NOTE}")
 1083:                 } else {
 1084:                     RECOVERED_NOTE.into()
 1085:                 }),
 1086:             },
 1087:         },
 1088:     )?;
 1089:     line.push(b'\n');
 1090:     file.write_all(&line)?;
 1091:     sync_data(&file)?;
 1092:     drop(file);
 1093:     filetime::set_file_mtime(partial, filetime::FileTime::from_system_time(modified))?;
 1094:     Ok(lost_start)
 1095: }
