  472: /// Write the run's spec and its `running` record. `None`, with a warning
  473: /// and why, when either cannot be kept — the command runs regardless.
  474: /// Blocking.
  475: fn begin_record(
  476:     machine: &Machine,
  477:     verb: &str,
  478:     args: &TransferArgs,
  479:     run_id: &str,
  480:     origin: RunOrigin,
  481: ) -> (Option<Recorded>, Option<String>) {
  482:     let unkept = |what: String| {
  483:         eprintln!("blit: warning: this run's job is not kept: {what}");
  484:         (None, Some(what))
  485:     };
  486:     let spec = match job_spec(verb, args, &machine.id) {
  487:         Ok(spec) => spec,
  488:         Err(what) => return unkept(what),
  489:     };
  490:     let store = RunStore::new(runs_dir(&machine.config_dir));
  491:     let mut record = RunRecord::starting(run_id, &spec);
  492:     record.saved_job = origin.saved_job;
  493:     if let Some((parent, attempt)) = origin.parent {
  494:         record.parent = Some(parent);
  495:         record.attempt = attempt.saturating_add(1);
  496:     }
  497:     match store.begin(&spec, &record) {
  498:         Ok(live) => (
  499:             Some(Recorded {
  500:                 store,
  501:                 spec,
  502:                 record,
  503:                 keep: machine.keep,
  504:                 _live: live,
  505:             }),
  506:             None,
  507:         ),
  508:         Err(error) => unkept(format!("{error}")),
  509:     }
  510: }
