  512: /// The run's record as the command ended, then pruning. Blocking.
  513: fn finish_record(
  514:     mut recorded: Recorded,
  515:     ending: Option<Ending>,
  516:     outcome: Outcome,
  517:     detail: Option<String>,
  518:     totals: Option<RunTotals>,
  519:     raws: &std::collections::HashMap<String, String>,
  520:     source_removed: bool,
  521: ) {
  522:     let record = &mut recorded.record;
  523:     record.ended_ms = Some(now_ms());
  524:     record.state = match ending {
  525:         Some(Ending::Detached { daemon, job_id }) => RunState::Waiting { daemon, job_id },
  526:         Some(Ending::Interrupted(_)) => RunState::Interrupted,
  527:         None => RunState::Finished,
  528:     };
  529:     record.outcome = match record.state {
  530:         RunState::Waiting { .. } => None,
  531:         _ => Some(outcome),
  532:     };
  533:     record.detail = detail;
  534:     record.source_removed = source_removed;
  535:     if let Some(totals) = totals {
